insert into public.collection_jurisdiction_profiles select * from jsonb_populate_recordset(null::public.collection_jurisdiction_profiles, '[{"board_vote_required":true,"citations":["Confirm your state statute and governing documents with association counsel."],"foreclosure_min_balance":null,"foreclosure_min_months":null,"last_reviewed":"2026-09-29","notice_method":"certified_mail","payment_plan_min_months":null,"payment_plan_offer_required":false,"pre_referral_notice_days":30,"state_code":"DEFAULT","state_name":"Default (no state profile)","summary":"Conservative baseline: written notice by certified mail at least 30 days before referral, and a recorded board decision to refer."},{"board_vote_required":true,"citations":["Cal. Civ. Code § 5660 (pre-lien notice)","§ 5665 (payment plan requests)","§ 5673 (board decision to record lien)","§ 5720 (foreclosure thresholds)"],"foreclosure_min_balance":1800,"foreclosure_min_months":12,"last_reviewed":"2026-09-29","notice_method":"certified_mail","payment_plan_min_months":null,"payment_plan_offer_required":false,"pre_referral_notice_days":30,"state_code":"CA","state_name":"California","summary":"Pre-lien notice by certified mail at least 30 days before recording a lien, including the owner''s right to dispute resolution; the board itself must approve recording a lien; judicial or nonjudicial foreclosure is barred below $1,800 in assessments or less than 12 months delinquent."},{"board_vote_required":true,"citations":["C.R.S. § 38-33.3-316.3 (HB22-1137)","C.R.S. § 38-33.3-316"],"foreclosure_min_balance":null,"foreclosure_min_months":6,"last_reviewed":"2026-09-29","notice_method":"certified_mail","payment_plan_min_months":18,"payment_plan_offer_required":true,"pre_referral_notice_days":30,"state_code":"CO","state_name":"Colorado","summary":"Before referring an account to a collection agency or attorney the association must send notice by certified mail, offer a payment plan of at least 18 months, and the board must formally vot